use std::{env,fs::File,io::{self,Read,Write}};
const I:usize=784;const H:usize=128;const O:usize=10;
struct M{w1:Vec<f32>,b1:Vec<f32>,w2:Vec<f32>,b2:Vec<f32>}
fn load_model(p:&str)->io::Result<M>{let mut b=Vec::new();File::open(p)?.read_to_end(&mut b)?;let mut q=0;let mut take=|n:usize|{let mut v=Vec::with_capacity(n);for _ in 0..n{v.push(f32::from_le_bytes([b[q],b[q+1],b[q+2],b[q+3]]));q+=4}v};Ok(M{w1:take(I*H),b1:take(H),w2:take(H*O),b2:take(O)})}
fn pgm(p:&str)->io::Result<Vec<f32>>{let mut b=Vec::new();File::open(p)?.read_to_end(&mut b)?;let mut toks=b.split(|c|*c==b' '||*c==b'\n'||*c==b'\r'||*c==b'\t').filter(|x|!x.is_empty());let magic=toks.next().unwrap();if magic!=b"P5"&&magic!=b"P2"{return Err(io::Error::new(io::ErrorKind::InvalidData,"expected P5/P2"))}let w:usize=std::str::from_utf8(toks.next().unwrap()).unwrap().parse().unwrap();let h:usize=std::str::from_utf8(toks.next().unwrap()).unwrap().parse().unwrap();let max:f32=std::str::from_utf8(toks.next().unwrap()).unwrap().parse::<f32>().unwrap();if w!=28||h!=28{return Err(io::Error::new(io::ErrorKind::InvalidData,"image must be 28x28"))}let mut x=Vec::with_capacity(I);if magic==b"P2"{for _ in 0..I{x.push(std::str::from_utf8(toks.next().unwrap()).unwrap().parse::<f32>().unwrap()/max)}}else{let hdr=b.windows(2).position(|z|z==b"\n\n").unwrap_or(0)+2;for &v in &b[hdr..hdr+I]{x.push(v as f32/max)}}Ok(x)}
fn infer(m:&M,x:&[f32]){let mut z=[0.;H];for j in 0..H{let mut v=m.b1[j];for i in 0..I{v+=m.w1[j*I+i]*x[i]}z[j]=v.max(0.)}let mut p=[0.;O];let mut mx:f32=-1e9;for k in 0..O{let mut v=m.b2[k];for j in 0..H{v+=m.w2[k*H+j]*z[j]}p[k]=v;mx=mx.max(v)}let mut s=0.;for v in p.iter_mut(){*v=(*v-mx).exp();s+=*v}for v in p.iter_mut(){*v/=s}let k=(0..O).max_by(|&a,&b|p[a].total_cmp(&p[b])).unwrap();println!("predicted={} confidence={:.2}%",k,100.*p[k]);}
fn generate(images:&str,labels:&str,class:u8,out:&str)->io::Result<()>{let mut ib=Vec::new();let mut lb=Vec::new();File::open(images)?.read_to_end(&mut ib)?;File::open(labels)?.read_to_end(&mut lb)?;let n=u32::from_be_bytes([lb[4],lb[5],lb[6],lb[7]])as usize;let mut sum=vec![0u32;I];let mut count=0;for s in 0..n{if lb[8+s]==class{let o=16+s*I;for i in 0..I{sum[i]+=ib[o+i]as u32}count+=1}}let mut f=File::create(out)?;writeln!(f,"P5\n28 28\n255")?;for v in sum{f.write_all(&[(v/count as u32)as u8])?}println!("generated class prototype {} from {} samples: {}",class,count,out);Ok(())}
fn main()->io::Result<()>{let a:Vec<String>=env::args().collect();match a.get(1).map(String::as_str){Some("generate")=>generate(&a[2],&a[3],a[4].parse().unwrap(),&a[5]),Some("infer")=>{let m=load_model(&a[2])?;let x=pgm(&a[3])?;infer(&m,&x);Ok(())},_=>{println!("generate <images> <labels> <class> <out.pgm>\ninfer <model> <image.pgm>");Ok(())}}}
